use crate::app::ArxivManager;
use crate::utils::config::{self, Config};
use iced::{Application, Settings};
use std::sync::Arc;

fn main() -> iced::Result {
    // 初始化日志
    setup_logging();

    // 加载配置
    let config = match config::load_config() {
        Ok(config) => Arc::new(config),
        Err(e) => {
            eprintln!("Failed to load config: {}", e);
            Arc::new(Config::default())
        }
    };

    // 启动 GUI 应用
    ArxivManager::run(Settings {
        window: iced::window::Settings {
            size: (1200, 800),
            min_size: Some((800, 600)),
            icon: get_app_icon(),
            ..Default::default()
        },
        default_font: Some(include_bytes!("../assets/fonts/NotoSans-Regular.ttf")),
        antialiasing: true,
        flags: config,
        ..Default::default()
    })
}

fn setup_logging() {
    use fern::colors::{Color, ColoredLevelConfig};
    let colors = ColoredLevelConfig::new()
        .error(Color::Red)
        .warn(Color::Yellow)
        .info(Color::Green)
        .debug(Color::Blue)
        .trace(Color::BrightBlack);

    fern::Dispatch::new()
        .format(move |out, message, record| {
            out.finish(format_args!(
                "[{} {} {}] {}",
                chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
                colors.color(record.level()),
                record.target(),
                message
            ))
        })
        .level(log::LevelFilter::Info)
        .chain(std::io::stdout())
        .chain(fern::log_file("arxiv-manager.log").unwrap())
        .apply()
        .unwrap();

    log::info!("Logger initialized");
}

fn get_app_icon() -> Option<iced::window::Icon> {
    let icon_data = include_bytes!("../assets/icon.png");
    match iced::window::Icon::from_rgba(
        // 这里需要处理图像数据，实际代码会更复杂
        vec![0; 32 * 32 * 4], 
        32, 
        32
    ) {
        Ok(icon) => Some(icon),
        Err(e) => {
            log::error!("Failed to load icon: {}", e);
            None
        }
    }
}
