```rust
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum PaperStatus {
    New,
    Downloading(u8), // 进度百分比
    Downloaded,
    Error(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Paper {
    pub paper_id: String,
    pub title: String,
    pub authors: Vec<String>,
    pub abstract_text: String,
    pub categories: Vec<String>,
    pub publish_date: Option<DateTime<Utc>>,
    pub update_date: Option<DateTime<Utc>>,
    pub pdf_url: String,
    pub web_url: String,
    pub local_path: Option<PathBuf>,
    pub status: PaperStatus,
    pub tags: HashSet<String>,
    pub notes: String,
    pub starred: bool,
    pub read: bool,
    pub download_time: Option<DateTime<Utc>>,
}

impl Paper {
    pub fn new(
        paper_id: String,
        title: String,
        authors: Vec<String>,
        abstract_text: String,
        categories: Vec<String>,
        pdf_url: String,
        web_url: String,
    ) -> Self {
        Self {
            paper_id,
            title,
            authors,
            abstract_text,
            categories,
            publish_date: None,
            update_date: None,
            pdf_url,
            web_url,
            local_path: None,
            status: PaperStatus::New,
            tags: HashSet::new(),
            notes: String::new(),
            starred: false,
            read: false,
            download_time: None,
        }
    }

    pub fn format_filename(&self) -> String {
        // 从发布日期获取年月
        let yymm = if let Some(date) = self.publish_date {
            format!("{}{}", date.format("%y"), date.format("%m"))
        } else {
            // 从ID中提取
            let parts: Vec<&str> = self.paper_id.split('.').collect();
            if parts.len() >= 2 && parts[0].len() >= 2 {
                let yy = &parts[0][parts[0].len() - 2..];
                let mm = if parts[1].len() >= 2 { &parts[1][..2] } else { "xx" };
                format!("{}{}", yy, mm)
            } else {
                "xxxx".to_string()
            }
        };

        // 提取ID号部分
        let id_num = if self.paper_id.contains('.') {
            self.paper_id.split('.').nth(1).unwrap_or("xxxx")
        } else {
            "xxxx"
        };

        // 格式化标题
        let safe_title = self.title
            .replace('/', "_")
            .replace('\\', "_")
            .replace(':', "_")
            .replace('?', "")
            .replace('*', "")
            .replace('"', "")
            .replace('<', "")
            .replace('>', "")
            .replace('|', "")
            .replace('\n', " ")
            .trim()
            .to_string();

        // 限制标题长度
        let safe_title = if safe_title.len() > 100 {
            format!("{}...", &safe_title[..97])
        } else {
            safe_title
        };

        // 最终文件名格式: [yymm.xxxx]title.pdf
        format!("[{}.{}]{}.pdf", yymm, id_num, safe_title)
    }
}
