use anyhow::Result;
use directories::ProjectDirs;
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub download_dir: PathBuf,
    pub db_path: PathBuf,
    pub max_concurrent_downloads: usize,
    pub enable_auto_download: bool,
    pub auto_download_time: String,
    pub auto_download_categories: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        let project_dirs = ProjectDirs::from("com", "arxiv", "manager")
            .expect("Failed to determine project directories");

        let data_dir = project_dirs.data_dir();

        // 确保目录存在
        fs::create_dir_all(data_dir).ok();

        Self {
            download_dir: get_default_download_dir(),
            db_path: data_dir.join("papers.db"),
            max_concurrent_downloads: 3,
            enable_auto_download: false,
            auto_download_time: "03:00".to_string(),
            auto_download_categories: vec!["hep-th".to_string(), "gr-qc".to_string()],
        }
    }
}

pub fn load_config() -> Result<Config> {
    let project_dirs = ProjectDirs::from("com", "arxiv", "manager")
        .expect("Failed to determine project directories");

    let config_dir = project_dirs.config_dir();
    let config_path = config_dir.join("config.json");

    if config_path.exists() {
        let config_str = fs::read_to_string(config_path)?;
        let config: Config = serde_json::from_str(&config_str)?;
        Ok(config)
    } else {
        let config = Config::default();
        save_config(&config)?;
        Ok(config)
    }
}

pub fn save_config(config: &Config) -> Result<()> {
    let project_dirs = ProjectDirs::from("com", "arxiv", "manager")
        .expect("Failed to determine project directories");

    let config_dir = project_dirs.config_dir();
    fs::create_dir_all(config_dir)?;

    let config_path = config_dir.join("config.json");
    let config_str = serde_json::to_string_pretty(config)?;
    fs::write(config_path, config_str)?;

    Ok(())
}

fn get_default_download_dir() -> PathBuf {
    let home_dir = dirs::home_dir().expect("Failed to determine home directory");
    home_dir.join("Documents").join("ArxivPapers")
}
