use crate::models::paper::Paper;

pub fn generate_bibtex(paper: &Paper) -> String {
    let first_author = paper.authors.first()
        .map(|a| a.split_whitespace().last().unwrap_or("Unknown"))
        .unwrap_or("Unknown");

    let year = paper.publish_date
        .map(|d| d.format("%Y").to_string())
        .unwrap_or_else(|| "YYYY".to_string());

    let cite_key = format!("{}{}{}",
        first_author,
        year,
        paper.paper_id.split('.').last().unwrap_or("xxxx")
    );

    let authors = paper.authors.join(" and ");

    format!(
        "@article{{{},\n  title = {{{}}},\n  author = {{{}}},\n  journal = {{arXiv preprint arXiv:{}}},\n  year = {{{}}},\n  url = {{https://arxiv.org/abs/{}}},\n}}",
        cite_key,
        paper.title,
        authors,
        paper.paper_id,
        year,
        paper.paper_id
    )
}
