impl Scheduler {
    pub fn new() -> Self {
        Self { running: false }
    }

    pub fn start(&mut self) {
        self.running = true;
        log::info!("Scheduler started");
    }

    pub fn stop(&mut self) {
        self.running = false;
        log::info!("Scheduler stopped");
    }

    pub fn is_running(&self) -> bool {
        self.running
    }
}
